E["Fehlermeldungen ausblenden"] = "Hide error messages"
E["Rote Meldungen in der Bildschirmmitte verschwinden, z. B. „Nicht genug Mana“, „Fähigkeit noch nicht bereit“ oder „Außer Reichweite“.\n\n„Taschen voll“ und „Questlog voll“ bleiben sichtbar. Gelbe Questfortschritte sind nicht betroffen."] = "Red messages in the middle of the screen disappear, e.g. “Not enough mana”, “Ability is not ready yet” or “Out of range”.\n\n“Inventory is full” and “Quest log is full” stay visible. Yellow quest progress is not affected."
E["Haltbarkeit |cff%s%d %%|r"] = "Durability |cff%s%d %%|r"
E["Haltbarkeit –"] = "Durability –"
E["Haltbarkeit"] = "Durability"
E["Keine Ausrüstung mit Haltbarkeit angelegt."] = "No equipped items with durability."
E["Shift + ziehen zum Verschieben"] = "Shift + drag to move"
E["Haltbarkeit anzeigen"] = "Show durability"
E["Kleine Anzeige am Bildschirm mit der Haltbarkeit deines am stärksten beschädigten Ausrüstungsteils – grün, gelb oder rot. Der Tooltip listet alle Teile.\n\nMit Shift + linker Maustaste verschiebst du die Anzeige."] = "Small on-screen display with the durability of your most damaged item – green, yellow or red. The tooltip lists all items.\n\nShift + left mouse button moves the display."

